  const next = booking({
    id: operation.id,
    day: operation.day,
    tenant: previous.tenant,
    units: operation.units ?? previous.units
  });
  return ledger.reserve(next);
}
import {booking, day} from "../common/request.mjs";

export function bookArchive(ledger, input) {
