import {booking, equivalent} from "../common/request.mjs";
import {renew} from "../common/renewals.mjs";

export function studioCapacity(catalog, tenant) {
  return catalog.studios.get(tenant) ?? catalog.default;
}

export function bookStudio(ledger, input, catalog) {
  const request = booking(input);
  // Resolve identity before admission: replays (including cancelled bookings)
  // must not be reconsidered against today's remaining allocation.
  const previous = ledger.inspect(request.id);
  if (previous) {
    if (!equivalent(previous, request)) return {status: "conflict", id: request.id};
    return {status: previous.active ? "replay" : "cancelled", id: request.id};
  }
  const cap = studioCapacity(catalog, request.tenant);
  const used = ledger.usage(request.tenant, request.day);
  if (used + request.units > cap) {
    return {status: "full", id: request.id, remaining: Math.max(0, cap - used)};
  }
  ledger.post(request);
  return {status: "booked", id: request.id, remaining: cap - used - request.units};
}

export function renewStudio(ledger, operation, catalog) {
  // Keep the shared renewal's inheritance and validation rules, but admit the
  // resulting booking through Studio rather than the platform default.
  return renew({
    inspect: id => ledger.inspect(id),
    reserve: request => bookStudio(ledger, request, catalog)
  }, operation);
}
EOF
