import test from "node:test";
import assert from "node:assert/strict";
import {planner, apply} from "./replay.mjs";

const catalog = () => ({default:5, studios:new Map([["orchid", 8], ["iris", 2]])});
const book = (id, units, extra = {}) => ({action:"book", service:"studio",
  tenant:"orchid", day:"2025-04-02", id, units, ...extra});

test("Studio allocations, including lower overrides, are tenant/day scoped", () => {
  const dispatch = planner(catalog());
  assert.deepEqual(dispatch(book("first", 7)), {status:"booked", id:"first", remaining:1});
  assert.deepEqual(dispatch(book("too-many", 2)), {status:"full", id:"too-many", remaining:1});
  assert.equal(dispatch(book("last", 1)).remaining, 0);
  assert.equal(dispatch(book("other-day", 8, {day:"2025-04-03"})).status, "booked");
  assert.equal(dispatch(book("lower", 3, {tenant:"iris"})).status, "full");
  assert.equal(dispatch(book("fallback", 5, {tenant:"lily"})).remaining, 0);
  assert.equal(dispatch(book("fallback-full", 1, {tenant:"lily"})).status, "full");
  assert.equal(dispatch(book("archive-full", 6, {service:"archive"})).status, "full");
  assert.equal(dispatch(book("archive", 5, {service:"archive"})).status, "booked");
});

test("replays, conflicts, cancellations and imports retain journal semantics", () => {
  const dispatch = planner(catalog());
  const original = book("first", 8);
  dispatch(original);
  assert.deepEqual(dispatch(original), {status:"replay", id:"first"});
  assert.equal(dispatch({...original, units:7}).status, "conflict");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "cancelled");
  assert.equal(dispatch(original).status, "cancelled");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "replay");
  assert.equal(dispatch(book("replacement", 8)).status, "booked");
  assert.deepEqual(dispatch({service:"studio", action:"usage", tenant:"orchid", day:original.day}), {units:8});
  assert.equal(dispatch({...book("backfill", 10), action:"import"}).status, "imported");
  assert.equal(dispatch({...book("backfill", 10)}).status, "replay");
  assert.deepEqual(dispatch(book("overbooked", 1)), {status:"full", id:"overbooked", remaining:0});
  const summary = dispatch({service:"studio", action:"summary"});
  assert.equal(summary.occupied.length, 2);
  assert.equal(summary.events.length, 4);
});

test("renewals use the inherited tenant allocation and preserve replay behavior", () => {
  const dispatch = planner(catalog());
  dispatch(book("source", 7));
  const renewal = {service:"studio", action:"renew", previous:"source", id:"next", day:"2025-05-02"};
  assert.deepEqual(dispatch(renewal), {status:"booked", id:"next", remaining:1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units:6}).status, "conflict");
  assert.deepEqual(dispatch({...renewal, id:"overflow", units:2}), {status:"full", id:"overflow", remaining:1});
  dispatch({service:"studio", action:"cancel", id:"next"});
  assert.equal(dispatch(renewal).status, "cancelled");
  dispatch({service:"studio", action:"cancel", id:"source"});
  assert.deepEqual(dispatch(renewal), {status:"missing", id:"source"});
  dispatch(book("default-source", 5, {tenant:"lily"}));
  assert.equal(dispatch({...renewal, previous:"default-source", id:"default-next", units:6}).status, "full");
  dispatch(book("low-source", 2, {tenant:"iris"}));
  assert.equal(dispatch({...renewal, previous:"low-source", id:"low-next", units:3}).status, "full");
  dispatch(book("archive-source", 5, {service:"archive"}));
  assert.equal(dispatch({...renewal, service:"archive", previous:"archive-source", id:"archive-next", units:6}).status, "full");
  assert.deepEqual(apply(dispatch, book("bad", 0)), {status:"invalid", field:"units"});
});
EOF
