import test from "node:test";
import assert from "node:assert/strict";
import {mkdtempSync, readFileSync, writeFileSync, rmSync} from "node:fs";
import {tmpdir} from "node:os";
import {join} from "node:path";
import {fileURLToPath} from "node:url";
import {execFileSync, spawnSync} from "node:child_process";

const script = fileURLToPath(new URL("./utilization.mjs", import.meta.url));
const read = path => JSON.parse(readFileSync(path, "utf8"));
const cell = (tenant, day, service = "studio") => ({service, tenant, day,
  edition:"old", cap:5, used:4, available:1});

function fixture(t) {
  const dir = mkdtempSync(join(tmpdir(), "studio-calendar-"));
  t.after(() => rmSync(dir, {recursive:true, force:true}));
  const feed = join(dir, "feed.json"), diary = join(dir, "diary.json");
  const source = {
    edition:"orchid-quota",
    window:{service:"studio", tenant:"orchid", from:"2025-04-02", through:"2025-04-03"},
    subscriptions:[{service:"studio", tenant:"orchid"}, {service:"studio", tenant:"iris"},
      {service:"archive", tenant:"orchid"}],
    days:["2025-04-01", "2025-04-02", "2025-04-03", "2025-04-04"],
    operations:[
      {action:"book", service:"studio", tenant:"orchid", id:"source", day:"2025-03-01", units:7},
      {action:"renew", service:"studio", previous:"source", id:"renewal", day:"2025-04-02"},
      {action:"book", service:"studio", tenant:"orchid", id:"cancel-me", day:"2025-04-03", units:8},
      {action:"cancel", service:"studio", id:"cancel-me"}
    ]
  };
  const untouched = [cell("orchid", "2025-04-01"), cell("orchid", "2025-04-04"),
    cell("iris", "2025-04-02"), cell("orchid", "2025-04-02", "archive")];
  writeFileSync(feed, JSON.stringify(source));
  writeFileSync(diary, JSON.stringify([...untouched, cell("orchid", "2025-04-03")]));
  return {feed, diary, source, untouched};
}

test("publication replays the full feed, scopes inclusive dates, and is idempotent", t => {
  const {feed, diary, untouched} = fixture(t);
  const output = execFileSync(process.execPath, [script, "publish-calendar", feed, diary], {encoding:"utf8"});
  assert.deepEqual(JSON.parse(output), {edition:"orchid-quota", rows:2});
  const rows = read(diary);
  assert.deepEqual(rows.slice(0, untouched.length), untouched);
  const target = rows.filter(r => r.service === "studio" && r.tenant === "orchid" &&
    r.day >= "2025-04-02" && r.day <= "2025-04-03").sort((a,b) => a.day.localeCompare(b.day));
  assert.deepEqual(target, [
    {service:"studio", tenant:"orchid", day:"2025-04-02", edition:"orchid-quota", cap:8, used:7, available:1},
    {service:"studio", tenant:"orchid", day:"2025-04-03", edition:"orchid-quota", cap:8, used:0, available:8}
  ]);
  const once = readFileSync(diary, "utf8");
  execFileSync(process.execPath, [script, "publish-calendar", feed, diary]);
  assert.equal(readFileSync(diary, "utf8"), once);
});

test("single-day Archive publication retains its default and other audiences", t => {
  const {feed, diary, source} = fixture(t);
  source.window = {service:"archive", tenant:"orchid", from:"2025-04-02", through:"2025-04-02"};
  source.operations.push({service:"archive", action:"book", tenant:"orchid", id:"archive", units:3, day:"2025-04-02"});
  writeFileSync(feed, JSON.stringify(source));
  const before = read(diary);
  execFileSync(process.execPath, [script, "publish-calendar", feed, diary]);
  assert.deepEqual(read(diary), before.map(row => row.service !== "archive" ? row :
    {...row, edition:"orchid-quota", cap:5, used:3, available:2}));
